import re


def eval_expression(expr):
    """Evaluate an arithmetic expression with +, -, *, /, and parentheses."""

    expr = expr.strip()
    if not expr:
        raise ValueError("Empty expression")

    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))"
    )

    tokens = []
    pos = 0

    while pos < len(expr):
        match = token_pattern.match(expr, pos)
        if not match:
            raise ValueError(f"Invalid character at position {pos}")

        number, operator = match.groups()
        if number is not None:
            value = float(number) if "." in number else int(number)
            tokens.append(("number", value))
        else:
            tokens.append((operator, operator))

        pos = match.end()

    index = 0

    def peek():
        return tokens[index][0] if index < len(tokens) else None

    def consume(expected=None):
        nonlocal index
        token = tokens[index] if index < len(tokens) else None

        if token is None:
            raise ValueError("Unexpected end of expression")
        if expected is not None and token[0] != expected:
            raise ValueError(f"Expected {expected!r}")

        index += 1
        return token

    def parse_expression():
        value = parse_term()

        while peek() in ("+", "-"):
            operator = consume()[0]
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        value = parse_factor()

        while peek() in ("*", "/"):
            operator = consume()[0]
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        if peek() == "+":
            consume("+")
            return parse_factor()

        if peek() == "-":
            consume("-")
            return -parse_factor()

        if peek() == "(":
            consume("(")
            value = parse_expression()
            consume(")")
            return value

        if peek() == "number":
            return consume("number")[1]

        raise ValueError("Expected a number or parenthesized expression")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError("Unexpected token")

    return result
